// Minimize total energy times final simulation clock in the supplied simulator.
#include "scheduler.hpp"
#include "ready_queue.hpp"

#include <algorithm>
#include <array>
#include <deque>
#include <iomanip>
#include <limits>
#include <optional>
#include <unordered_map>

/*
 * Ideas:
 * 1. Intelligently choose between big and small cores. Big cores for more work unit jobs, small cores otherwise
 * 4. Adjust Pstate based on IO bound operations
 */

// Compile-time controls allow paired benchmarks without changing the workload.
#ifndef EEC_SMALL_CORES
#define EEC_SMALL_CORES 4 // Number of small cores (IDs 4-7) enabled for work.
#endif
#ifndef EEC_BIG_CORES
#define EEC_BIG_CORES 4 // Number of big cores (IDs 0-3) enabled for work.
#endif
#ifndef EEC_PSTATE
#define EEC_PSTATE P3 // P-state used for normal execution.
#endif
#ifndef EEC_TAIL_DVFS
#define EEC_TAIL_DVFS 1 // Enable P3-to-P4 switching when a job can finish in one quantum.
#endif
#ifndef EEC_IDLE_TIMEOUT
// Maximum time an enabled core stays in C4 per idle episode, in raw simulator
// time units. Defaults to 10 timer quanta (10,000 units).
#define EEC_IDLE_TIMEOUT (10 * QUANTUM)
#endif
static_assert(EEC_IDLE_TIMEOUT > 0, "Idle timeout must be positive");

static_assert(EEC_SMALL_CORES >= 0 && EEC_SMALL_CORES <= 4, "Invalid small-core count");
static_assert(EEC_BIG_CORES >= 0 && EEC_BIG_CORES <= 4, "Invalid big-core count");
static_assert(EEC_SMALL_CORES + EEC_BIG_CORES > 0, "At least one core is needed");
static_assert(EEC_PSTATE >= P0 && EEC_PSTATE <= P4, "Invalid P-state");

namespace {
constexpr Time_t C4WakeTime = 10 * QUANTUM;
constexpr Time_t C6WakeTime = 2000 * QUANTUM;
constexpr Time_t WarmReserveTime = 100 * QUANTUM;
enum class CoreStatus { Ready, Running, Sleeping, Waking, Deepening };

struct CoreRecord {
    CoreStatus status = CoreStatus::Ready;
    ProcessId_t pid = 0;
    PState_t pstate = P0;
    bool enabled = false;
    CState_t idle_state = C1;
    Time_t idle_since = 0;
    Time_t wake_ready = 0;
};

struct ProcessRecord {
    Time_t arrival;
    bool dispatched = false;
    std::optional<CPUId_t> core;
};

std::array<CoreRecord, 8> cores;
ReadyQueue ready;
struct Arrival { Time_t time; Time_t work; };
std::deque<Arrival> recent_arrivals;
std::unordered_map<ProcessId_t, ProcessRecord> processes;
bool initialized = false;
std::uint64_t created = 0;
std::uint64_t completed = 0;
std::uint64_t initial_work = 0;
std::uint64_t wake_requests = 0;
std::uint64_t wake_completions = 0;
std::uint64_t tail_changes = 0;
Time_t total_wait = 0;
Time_t maximum_wait = 0;

// Inputs: core ID, current time, and whether to extend its warm budget.
// Postcondition: unused enabled cores enter C4 within their idle budget and
// request C6 after expiry; disabled cores enter C6 immediately.
void SleepCore(CPUId_t core, Time_t now, bool warm_reserve) {
    CoreRecord &record = cores[core];
    if (record.status != CoreStatus::Ready && record.status != CoreStatus::Sleeping)
        return;
    const Time_t budget = warm_reserve ? std::max<Time_t>(EEC_IDLE_TIMEOUT, WarmReserveTime)
                                      : EEC_IDLE_TIMEOUT;
    const CState_t state = record.enabled && now - record.idle_since < budget
                               ? C4 : C6;
    if (record.status == CoreStatus::Sleeping) {
        if (record.idle_state == C4 && state == C6) {
            record.status = CoreStatus::Deepening;
            record.wake_ready = now + C4WakeTime;
            SetCState(core, C6);
        }
    } else {
        SetCState(core, state);
        record.idle_state = state;
        record.status = CoreStatus::Sleeping;
    }
}

// Inputs: none. Output: none. Postcondition: core ownership and enabled flags
// are initialized once, leaving cores ready for the first scheduling pass.
void Initialize() {
    if (initialized)
        return;
    initialized = true;
    for (CPUId_t core = 0; core < cores.size(); ++core) {
        cores[core].pid = InvalidProcessId();
        cores[core].idle_since = Now();
        // enable the core ids according to the simulator
        cores[core].enabled = static_cast<int>(core) < EEC_BIG_CORES ||
                              (core >= 4 && core < 4 + EEC_SMALL_CORES);
        // Constructors establish C1. ScheduleReadyWork dispatches admitted
        // work before putting unused cores into their configured idle states.
    }
}

// Inputs: core ID and remaining work. Output: selected P-state. Postcondition:
// scheduler state is unchanged; a short final interval may select P4.
PState_t StateForWork(CPUId_t core, Time_t remaining) {
    if (EEC_TAIL_DVFS) {
        // At a timer interrupt, P4 completes <=120 small-core work units
        // (<=200 on a big core) in one quantum for less energy than P3.
        // These thresholds come from libsim.so: CPU::BeforeScheduler applies
        // speed[P4] * scale[core type] * elapsed, with P4 speed 0.20, big
        // scale 1.0, and small scale 0.60. For QUANTUM=1000 (sim_types.h),
        // that is 200 work units on a big core and 120 on a small core.
        const Time_t p4_work_per_quantum = core >= 4 ? 120 : 200;
        if (remaining > 0 && remaining <= p4_work_per_quantum)
            return P4;
    }
    return EEC_PSTATE;
}

// Inputs: process ID, ready core ID, and current time. Output: none.
// Postcondition: the process context runs on that core at its selected
// P-state, and first-dispatch wait is recorded when applicable.
void Dispatch(ProcessId_t pid, CPUId_t core, Time_t now) {
    // Verify the target core is ready and not already assigned to a process.
    CoreRecord &record = cores[core];
    if (record.status != CoreStatus::Ready || record.pid != InvalidProcessId())
        ThrowException("Dispatch requires an unowned core in C1");

    // Look up the process record and reject IDs that were never created.
    auto process_entry = processes.find(pid);
    if (process_entry == processes.end())
        // unable to resolve pid in processes map
        ThrowException("Dispatch received an unknown process");
    ProcessRecord &process_record = process_entry->second;

    // Count the process's ready-queue wait once, on its first dispatch.
    // Keep track of total weight/max weight for metrics printed upon exit
    if (!process_record.dispatched) {
        const Time_t wait = now - process_record.arrival;
        total_wait += wait;
        if (wait > maximum_wait)
            maximum_wait = wait;
        process_record.dispatched = true;
    }

    // Choose a P-state based on the core type and the process's remaining work.
    const PState_t state = StateForWork(core, GetRemaining(pid));

    // Load the saved process context, then start execution on the core.
    LoadContext(pid, core);
    RunCore(core);
    // RunCore resets the execution timestamp. No work is double-counted
    // when SetPState is applied immediately afterward at the same time.

    // Apply the selected P-state and record the core's new ownership and state.
    SetPState(core, state);
    record.pid = pid;
    record.pstate = state;
    record.status = CoreStatus::Running;
    record.idle_state = C0;
    process_record.core = core;
}

Time_t WorkPerQuantum(CPUId_t core, PState_t state) {
    constexpr std::array<Time_t, 5> big_work{1000, 800, 600, 400, 200};
    constexpr std::array<Time_t, 5> small_work{600, 480, 360, 240, 120};
    return core < 4 ? big_work[state] : small_work[state];
}

Time_t ExecutionTime(CPUId_t core, Time_t work, PState_t state) {
    const Time_t per_quantum = WorkPerQuantum(core, state);
    return ((std::max<Time_t>(work, 1) + per_quantum - 1) / per_quantum) * QUANTUM;
}

double ExecutionEnergy(CPUId_t core, Time_t work, PState_t state) {
    constexpr std::array<double, 5> big_energy{22000, 16000, 10800, 5600, 3600};
    const double interval = big_energy[state] * (core < 4 ? 1.0 : 0.5);
    double energy = static_cast<double>(ExecutionTime(core, work, state) / QUANTUM) * interval;
    const Time_t remainder = work % WorkPerQuantum(core, state);
    if (EEC_TAIL_DVFS && remainder > 0 && remainder <= WorkPerQuantum(core, P4))
        energy -= interval - big_energy[P4] * (core < 4 ? 1.0 : 0.5);
    return energy;
}

// Project the whole admitted batch, including currently running work, idle
// residence, wake delays, and accumulated energy. A single optional arrival
// from observed history lets idle decisions compare C4 with a future C6 wake.
// Ownership and hardware state are never changed by this forecast.
long double ProjectedEDP(Time_t now, double consumed,
                         std::optional<CPUId_t> wake = std::nullopt,
                         std::optional<CPUId_t> reserve = std::nullopt,
                         std::optional<Arrival> future = std::nullopt) {
    const Time_t unavailable = std::numeric_limits<Time_t>::max();
    struct ForecastCore {
        Time_t available, idle_begin, idle_end, finish;
        double energy;
        bool c4;
    };
    std::array<ForecastCore, 8> plan;
    for (CPUId_t core = 0; core < cores.size(); ++core) {
        const CoreRecord &record = cores[core];
        ForecastCore &prediction = plan[core];
        prediction = {unavailable, now, now, now, 0.0, false};
        if (!record.enabled)
            continue;
        const Time_t budget = reserve && *reserve == core
                                  ? std::max<Time_t>(EEC_IDLE_TIMEOUT, WarmReserveTime)
                                  : EEC_IDLE_TIMEOUT;
        if (record.status == CoreStatus::Running) {
            const Time_t work = GetRemaining(record.pid);
            prediction.available = now + ExecutionTime(core, work, record.pstate);
            prediction.finish = prediction.idle_begin = prediction.available;
            prediction.idle_end = prediction.available + budget + C4WakeTime;
            prediction.energy = ExecutionEnergy(core, work, record.pstate);
            prediction.c4 = true;
        } else if (record.status == CoreStatus::Waking) {
            prediction.available = std::max(now, record.wake_ready);
            prediction.c4 = record.idle_state == C4;
            if (prediction.c4)
                prediction.idle_end = prediction.available < record.idle_since + budget
                                          ? record.idle_since + budget + C4WakeTime
                                          : prediction.available;
        } else if (record.status == CoreStatus::Ready) {
            prediction.available = now;
            prediction.c4 = now < record.idle_since + budget;
            if (prediction.c4)
                prediction.idle_end = record.idle_since + budget + C4WakeTime;
        } else if (record.status == CoreStatus::Sleeping && record.idle_state == C4) {
            prediction.c4 = true;
            prediction.idle_end = record.idle_since + budget + C4WakeTime;
        } else if (record.status == CoreStatus::Deepening) {
            prediction.c4 = true;
            prediction.idle_end = std::max(now, record.wake_ready);
        }
        if (wake && *wake == core) {
            if (record.status == CoreStatus::Deepening)
                prediction.available = std::max(now, record.wake_ready) + C6WakeTime;
            else if (record.idle_state == C6) {
                prediction.available = now + C6WakeTime;
                prediction.c4 = false;
            } else {
                prediction.available = now + C4WakeTime;
                prediction.c4 = true;
                prediction.idle_end = prediction.available;
            }
        }
    }

    const auto idle_energy = [&](CPUId_t core, Time_t until) {
        const ForecastCore &prediction = plan[core];
        return prediction.c4 ? (core < 4 ? 1.6 : 0.8) *
            std::max<Time_t>(0, std::min(until, prediction.idle_end) - prediction.idle_begin) : 0.0;
    };
    const auto assign = [&](CPUId_t core, Time_t start, Time_t work) {
        ForecastCore &prediction = plan[core];
        const PState_t state = StateForWork(core, work);
        prediction.energy += idle_energy(core, start) + ExecutionEnergy(core, work, state);
        prediction.available = start + ExecutionTime(core, work, state);
        prediction.finish = prediction.idle_begin = prediction.available;
        const Time_t budget = reserve && *reserve == core
                                  ? std::max<Time_t>(EEC_IDLE_TIMEOUT, WarmReserveTime)
                                  : EEC_IDLE_TIMEOUT;
        prediction.idle_end = prediction.available + budget + C4WakeTime;
        prediction.c4 = true;
    };
    for (ProcessId_t pid : ready.Entries()) {
        const Time_t work = GetRemaining(pid);
        std::optional<CPUId_t> selected;
        Time_t start = unavailable;
        for (unsigned position = 0; position < cores.size(); ++position) {
            const CPUId_t core = (position + 4) % cores.size();
            if (cores[core].enabled && (core >= 4 || work > 120) && plan[core].available < start) {
                selected = core;
                start = plan[core].available;
            }
        }
        if (!selected)
            return std::numeric_limits<long double>::infinity();
        assign(*selected, start, work);
    }
    if (future) {
        std::optional<CPUId_t> selected;
        Time_t start = unavailable;
        for (unsigned position = 0; position < cores.size(); ++position) {
            const CPUId_t core = (position + 4) % cores.size();
            const ForecastCore &prediction = plan[core];
            if (!cores[core].enabled || (core < 4 && future->work <= 120))
                continue;
            Time_t candidate;
            if (prediction.available != unavailable && future->time <= prediction.available)
                candidate = prediction.available;
            else if (prediction.c4 && future->time < prediction.idle_end - C4WakeTime)
                candidate = future->time + C4WakeTime;
            else
                candidate = std::max(future->time, prediction.idle_end) + C6WakeTime;
            if (candidate < start) {
                selected = core;
                start = candidate;
            }
        }
        if (!selected)
            return std::numeric_limits<long double>::infinity();
        // A C4 demand wake retains its source power until it really completes.
        if (plan[*selected].c4 && future->time < plan[*selected].idle_end - C4WakeTime)
            plan[*selected].idle_end = std::max(plan[*selected].idle_end, start);
        assign(*selected, start, future->work);
    }
    Time_t finish = now;
    for (const ForecastCore &prediction : plan)
        finish = std::max(finish, prediction.finish);
    long double energy = consumed;
    for (CPUId_t core = 0; core < cores.size(); ++core)
        energy += plan[core].energy + idle_energy(core, finish);
    return energy * finish;
}

// Short arrival streams use the measured EDP-winning policy. When current
// execution outlasts a cold wake, the admitted batch exposes an energy/time
// comparison that can hide wake latency behind its long running work.
bool HasLongRunningWork() {
    for (CPUId_t core = 0; core < cores.size(); ++core)
        if (cores[core].status == CoreStatus::Running &&
            ExecutionTime(core, GetRemaining(cores[core].pid), cores[core].pstate) > C6WakeTime)
            return true;
    return false;
}

// Keep at most one available core warm when observed demand falls just beyond
// the normal idle window. Dense bursts and long gaps retain the normal budget.
std::optional<CPUId_t> WarmReserve(Time_t now) {
    if (recent_arrivals.size() < 4 || now - recent_arrivals.back().time >= WarmReserveTime)
        return std::nullopt;
    const Time_t gap = (recent_arrivals.back().time - recent_arrivals.front().time) /
                      (recent_arrivals.size() - 1);
    if (gap <= EEC_IDLE_TIMEOUT || gap > WarmReserveTime)
        return std::nullopt;
    for (unsigned position = 0; position < cores.size(); ++position) {
        const CPUId_t core = (position + 4) % cores.size();
        const CoreRecord &record = cores[core];
        if (record.enabled && now - record.idle_since < WarmReserveTime &&
            (record.status == CoreStatus::Ready ||
             (record.status == CoreStatus::Sleeping && record.idle_state == C4))) {
            if (HasLongRunningWork()) {
                Time_t work = 0;
                for (const Arrival &arrival : recent_arrivals)
                    work += arrival.work;
                work /= recent_arrivals.size();
                const Arrival future{std::max(now, recent_arrivals.back().time + gap), work};
                const double consumed = GetTotalEnergyConsumed();
                if (ProjectedEDP(now, consumed, std::nullopt, core, future) >=
                    ProjectedEDP(now, consumed, std::nullopt, std::nullopt, future))
                    return std::nullopt;
            }
            return core;
        }
    }
    return std::nullopt;
}

// Compare first-dispatch times using actual running work and pending wakes.
// A quick C4 wake may overtake cold capacity that is already in flight.
// Keep the existing early C6 admission rule: delaying zero-energy cold wakes
// until current work fills their wake interval hurt continuing arrivals.
void WakeForPredictedWork(Time_t now) {
    if (!ready.Empty() && HasLongRunningWork()) {
        const double consumed = GetTotalEnergyConsumed();
        for (;;) {
            long double best = ProjectedEDP(now, consumed);
            std::optional<CPUId_t> selected;
            for (unsigned position = 0; position < cores.size(); ++position) {
                const CPUId_t core = (position + 4) % cores.size();
                const CoreRecord &record = cores[core];
                if (!record.enabled || (record.status != CoreStatus::Sleeping &&
                                        record.status != CoreStatus::Deepening))
                    continue;
                const long double candidate = ProjectedEDP(now, consumed, core);
                if (candidate < best) {
                    best = candidate;
                    selected = core;
                }
            }
            if (!selected || cores[*selected].status == CoreStatus::Deepening)
                return; // Reevaluate on the real deepening callback.
            CoreRecord &record = cores[*selected];
            record.wake_ready = now + (record.idle_state == C4 ? C4WakeTime : C6WakeTime);
            record.status = CoreStatus::Waking;
            ++wake_requests;
            SetCState(*selected, C1);
        }
    }
    if (ready.Empty() || std::none_of(cores.begin(), cores.end(), [](const CoreRecord &core) {
            return core.enabled && core.status == CoreStatus::Sleeping;
        }))
        return;

    const Time_t unavailable = std::numeric_limits<Time_t>::max();
    std::array<Time_t, 8> available;
    available.fill(unavailable);
    for (CPUId_t core = 0; core < cores.size(); ++core) {
        const CoreRecord &record = cores[core];
        if (!record.enabled)
            continue;
        if (record.status == CoreStatus::Running)
            available[core] = now + ExecutionTime(core, GetRemaining(record.pid), record.pstate);
        else if (record.status == CoreStatus::Waking)
            available[core] = std::max(now, record.wake_ready);
        else if (record.status == CoreStatus::Ready)
            available[core] = now;
    }

    for (ProcessId_t pid : ready.Entries()) {
        const Time_t work = GetRemaining(pid);
        std::optional<CPUId_t> selected;
        Time_t best_start = unavailable;
        // Existing capacity wins equal dispatch times. Account for preceding
        // queued work before using a core's capacity again in this forecast.
        for (unsigned position = 0; position < cores.size(); ++position) {
            const CPUId_t core = (position + 4) % cores.size();
            const CoreRecord &record = cores[core];
            if (!record.enabled || (core < 4 && work <= 120))
                continue;
            if (available[core] < best_start) {
                selected = core;
                best_start = available[core];
            }
        }
        for (unsigned position = 0; position < cores.size(); ++position) {
            const CPUId_t core = (position + 4) % cores.size();
            const CoreRecord &record = cores[core];
            if (!record.enabled || record.status != CoreStatus::Sleeping ||
                record.idle_state != C4 || (core < 4 && work <= 120))
                continue;
            const Time_t wake = now + C4WakeTime;
            if (wake < best_start) {
                selected = core;
                best_start = wake;
                break;
            }
        }
        if (!selected)
            break; // Deepening cores become eligible on their real callback.

        CoreRecord &record = cores[*selected];
        if (record.status == CoreStatus::Sleeping) {
            record.wake_ready = best_start;
            record.status = CoreStatus::Waking;
            ++wake_requests;
            SetCState(*selected, C1);
        }
        available[*selected] = best_start + ExecutionTime(*selected, work, StateForWork(*selected, work));
    }

    std::size_t waking = std::count_if(cores.begin(), cores.end(), [](const CoreRecord &core) {
        return core.status == CoreStatus::Waking;
    });
    for (unsigned pass = 0; pass < 2; ++pass) {
        for (unsigned position = 0; position < cores.size() && waking < ready.Size(); ++position) {
            const CPUId_t core = (position + 4) % cores.size();
            CoreRecord &record = cores[core];
            if (record.enabled && record.status == CoreStatus::Sleeping &&
                (record.idle_state == C4) == (pass == 0)) {
                record.wake_ready = now + (record.idle_state == C4 ? C4WakeTime : C6WakeTime);
                record.status = CoreStatus::Waking;
                ++wake_requests;
                SetCState(core, C1);
                ++waking;
            }
        }
    }
}

// Inputs: current time. Output: none. Postcondition: queued work is dispatched to
// available enabled cores; additional required cores are requested awake, and
// unused ready cores are put into their configured idle states.
void ScheduleReadyWork(Time_t now) {
    // Prefer ready small cores before experimental big-core configurations.
    for (unsigned position = 0; position < cores.size(); ++position) {
        // visits cores in this order as position goes from 0 to 7:
        // 4, 5, 6, 7, 0, 1, 2, 3
        // Small cores = 4, 5, 6, 7
        const CPUId_t core = (position + 4) % cores.size();
        if (!ready.Empty() && cores[core].enabled && cores[core].status == CoreStatus::Ready) {
            std::optional<ProcessId_t> pid;
            if (core < 4) {
                // High-perf cores. There's no reason to schedule here if time remaining is <= 120
                // (the amount of work a low-perf core can get done in one time quantum)
                pid = ready.PopNext(121);
            } else {
                pid = ready.PopNext();
            }
            if (pid)
                Dispatch(*pid, core, now);
        }
    }

    WakeForPredictedWork(now);

    const std::optional<CPUId_t> reserve = WarmReserve(now);
    for (CPUId_t core = 0; core < cores.size(); ++core)
        SleepCore(core, now, reserve && *reserve == core);
}
} // namespace

// Inputs: newly created process ID. Output: none. Postcondition: the process
// is recorded, counted, queued, and scheduled if capacity is available.
void CreateProcess(ProcessId_t pid) {
    Initialize();
    const Time_t work = GetRemaining(pid);
    const Time_t now = Now();
    if (work < 0 || !processes.emplace(pid, ProcessRecord{now, false, std::nullopt}).second)
        ThrowException("Invalid or duplicate process creation");
    ++created;
    initial_work += static_cast<std::uint64_t>(work);
    recent_arrivals.push_back({now, work});
    if (recent_arrivals.size() > 8)
        recent_arrivals.pop_front();
    ready.Enqueue(pid);
    ScheduleReadyWork(now);
}

// Inputs: completed process ID. Output: none. Postcondition: a validated
// completed process is removed, its core is released, and queued work is
// scheduled; invalid completion state raises an exception.
void ExitProcess(ProcessId_t pid) {
    auto process = processes.find(pid);
    if (process == processes.end() || !process->second.core)
        ThrowException("Completion does not match a running process");
    const CPUId_t owner = *process->second.core;
    if (owner >= cores.size() || cores[owner].status != CoreStatus::Running ||
        cores[owner].pid != pid || GetRemaining(pid) != 0)
        ThrowException("Completion does not match a running process");
    processes.erase(process);

    // BeforeScheduler has already detached this completed PID and set C1.
    // SaveContext here would incorrectly require a still-running C0 core.
    cores[owner].pid = InvalidProcessId();
    cores[owner].status = CoreStatus::Ready;
    cores[owner].idle_state = C1;
    cores[owner].idle_since = Now();
    ++completed;
    ScheduleReadyWork(Now());
}

// Inputs: timer timestamp.
// Output: none. Postcondition: eligible running jobs use the appropriate
// final-interval P-state, then ready work is scheduled.
void TimerInterrupt(Time_t now) {
    Initialize();
    if (EEC_TAIL_DVFS) {
        for (CPUId_t core = 0; core < cores.size(); ++core) {
            CoreRecord &record = cores[core];
            if (record.status != CoreStatus::Running)
                continue;
            const PState_t state = StateForWork(core, GetRemaining(record.pid));
            if (state != record.pstate) {
                // Reset the run timestamp so SetPState won't account this quantum twice.
                SaveContext(record.pid, core);
                LoadContext(record.pid, core);
                RunCore(core);
                SetPState(core, state);
                record.pstate = state;
                ++tail_changes;
            }
        }
    }
    ScheduleReadyWork(now);
}

// Inputs: core ID whose C-state transition completed. Output: none.
// Postcondition: a waking core becomes ready, or a deepening core becomes a C6
// sleeper, then queued work is rescheduled; unexpected completions raise an exception.
void CStateTransitionComplete(CPUId_t core) {
    if (core < cores.size() && cores[core].status == CoreStatus::Deepening) {
        cores[core].status = CoreStatus::Sleeping;
        cores[core].idle_state = C6;
        ScheduleReadyWork(Now());
        return;
    }
    if (core >= cores.size() || cores[core].status != CoreStatus::Waking)
        ThrowException("Unexpected C-state transition completion");
    cores[core].status = CoreStatus::Ready;
    cores[core].idle_state = C1;
    ++wake_completions;
    // Only dispatch queue entries here; other running cores may not yet have
    // advanced through their BeforeScheduler calls for this timestamp.
    ScheduleReadyWork(Now());
}

// Inputs: final simulation timestamp. Output: completion and energy metrics
// on stdout. Postcondition: verifies all jobs and contexts are finished before
// reporting; unfinished or owned work raises an exception.
void SimulationComplete(Time_t now) {
    if (!ready.Empty() || !processes.empty() || created != completed)
        ThrowException("Simulation stopped with unfinished scheduler work");
    for (const CoreRecord &record : cores)
        if (record.status == CoreStatus::Running || record.pid != InvalidProcessId())
            ThrowException("Simulation stopped with an owned CPU context");

    const double energy = GetTotalEnergyConsumed();
    const double lower_bound = static_cast<double>(initial_work) * (35.0 / 3.0);
    std::cout << std::setprecision(12)
              << "Run stopped at " << FormatTime(now) << " after consuming "
              << energy / 3600000000.0 << " kWh\n"
              << "Raw time: " << now << "; raw energy: " << energy
              << "; completed: " << completed << '/' << created << '\n'
              << "Mean/max dispatch wait (raw time): "
              << (created ? static_cast<double>(total_wait) / created : 0.0)
              << '/' << maximum_wait << "; wakes: " << wake_completions << '/' << wake_requests
              << "; tail P-state changes: " << tail_changes << '\n'
              << "Active-energy lower bound: " << lower_bound
              << "; overhead: " << (lower_bound ? 100.0 * (energy / lower_bound - 1.0) : 0.0)
              << "%\n"
              << "EDP (raw energy * final clock): "
              << static_cast<long double>(energy) * now << '\n';
}
